import java.time.LocalDate;

public class DateMathTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("daysBetween forward", 30L, DateMath.daysBetween(LocalDate.of(2026, 1, 1), LocalDate.of(2026, 1, 31)));
            check("daysBetween is absolute when reversed", 30L, DateMath.daysBetween(LocalDate.of(2026, 1, 31), LocalDate.of(2026, 1, 1)));
            check("daysBetween of the same date", 0L, DateMath.daysBetween(LocalDate.of(2026, 6, 15), LocalDate.of(2026, 6, 15)));
            check("daysBetween across a leap day", 2L, DateMath.daysBetween(LocalDate.of(2024, 2, 28), LocalDate.of(2024, 3, 1)));
            check("nextMonday from a Wednesday", LocalDate.of(2026, 8, 24), DateMath.nextMonday(LocalDate.of(2026, 8, 19)));
            check("nextMonday from a Monday is a week later", LocalDate.of(2026, 8, 24), DateMath.nextMonday(LocalDate.of(2026, 8, 17)));
            check("nextMonday from a Sunday", LocalDate.of(2026, 8, 17), DateMath.nextMonday(LocalDate.of(2026, 8, 16)));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

